export function FeatureCard({
  icon = "{{icon}}",
  title = "{{title}}",
  description = "{{description}}",
  badgeShape = "{{badgeShape}}",
  accent = "{{accent}}",
}) {
  const radius = { circle: "50%", square: "8px", hex: "22% 22% 40% 40% / 30% 30% 30% 30%" }[badgeShape] ?? "50%";
  return (
    <div style={{ font: "16px/1.5 system-ui, sans-serif", color: "#241430", maxWidth: 260, padding: 8 }}>
      <span aria-hidden="true" style={{ display: "inline-flex", alignItems: "center", justifyContent: "center",
        width: 44, height: 44, fontSize: 20, marginBottom: 14, background: accent, borderRadius: radius }}>{icon}</span>
      <h3 style={{ margin: "0 0 6px", fontSize: 17, fontWeight: 700 }}>{title}</h3>
      <p style={{ margin: 0, fontSize: 14, color: "#241430cc" }}>{description}</p>
    </div>
  );
}
